def calculate_E(a, b, c):
    S1 = a + b + c
    S2 = a*b + b*c + c*a
    S3 = a*b*c
    # E = (S1 * (S2 + 1)) / (4 * S3)
    numerator = S1 * (S2 + 1)
    denominator = 4 * S3
    if denominator == 0:
        return None
    return numerator / denominator

def check_triples(limit):
    results = {}
    triples = []
    for a in range(1, limit + 1):
        for b in range(a + 1, limit + 1):
            for c in range(b + 1, limit + 1):
                E = calculate_E(a, b, c)
                if E is not None and E == int(E):
                    n = int(E)
                    triples.append((a, b, c, n))
                    if n not in results:
                        results[n] = []
                    results[n].append((a, b, c))
    return results, triples

# Check up to a limit of 7
results, triples = check_triples(7)
print("Results for E values:")
for n, t_list in results.items():
    print(f"n={n}: Found {len(t_list)} triples. Examples: {t_list[:2]}")

print("\nAll found triples (a, b, c, n):")
print(triples)
